export function renderOverview(state=null) {
  const status=state?.life?.character?"CHARACTER CREATED":state?"CHARACTER NOT CREATED":"SIMULATION NOT STARTED";
  const summary=state?.finance?getFinanceSummary(state.finance):null;
  const liveStat=(label,value,detail,ico)=>`<article class="stat"><div class="stat-top"><span>${label}</span><i>${icon(ico)}</i></div><strong>${(value/100).toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2})}</strong><small><b></b>${detail}</small></article>`;
  const stats=summary?[liveStat("Available cash",summary.cash,"CREDITS", "wallet"),liveStat("Net worth",summary.netWorth,"ASSETS LESS LIABILITIES","chart"),liveStat("Recorded income",summary.income,"LIFETIME TO DATE","arrow"),liveStat("Outstanding debt",summary.liabilities,"CURRENT PRINCIPAL","shield")].join(""):[statCard("Available cash","wallet"),statCard("Net worth","chart"),statCard("Monthly income","arrow"),statCard("Outstanding debt","shield")].join("");
  const position=summary?`<div class="finance-overview"><div><small>ASSETS</small><b>${(summary.assets/100).toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2})}</b></div><div><small>LIABILITIES</small><b>${(summary.liabilities/100).toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2})}</b></div><div><small>LIQUID NET WORTH</small><b>${(summary.liquidNetWorth/100).toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2})}</b></div><div><small>RECORDED CASH FLOW</small><b>${(summary.netCashflow/100).toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2})}</b></div></div>`:emptyState("chart","Your financial picture starts here","Your household financial ledger will appear after you create a character.","AWAITING FIRST SAVE");
  return '<section class="welcome"><div class="welcome-copy"><label>— CAPITAL & CONSEQUENCE</label><h2>Every empire starts<br>with a <em>first decision.</em></h2><p>Build financial stability, make your capital work, and shape the companies and relationships that define your future.</p><div class="welcome-links"><a class="primary" href="#/personal" data-route="personal">Explore your profile ' + icon("arrow") + '</a><a href="#/finance" data-route="finance">Understand the numbers ' + icon("right") + '</a></div></div><div class="orbit" aria-hidden="true"><div class="orbit-one"></div><div class="orbit-two"></div><div class="orbit-core">N</div><span>01 / 09<br>YOUR JOURNEY</span></div><footer><span>PHASE 09 / BUSINESS OPERATIONS</span><span>' + status + '</span></footer></section>' +
    '<section class="stats">' + stats + '</section>' +
    '<section class="dash-grid"><article class="panel">' + panelTitle("Financial position", "Your balance sheet and cash flow will appear here.") + position + '</article><article class="panel">' + panelTitle("Your next moves", "The foundations of a stronger financial position.") + '<div class="moves"><a href="#/personal" data-route="personal"><b>01</b><span><strong>Create your character</strong><small>Choose a background and review your circumstances</small></span>' + icon("right") + '</a><a href="#/finance" data-route="finance"><b>02</b><span><strong>Prepare your financial foundation</strong><small>Review cash, budgets, debt and journal activity</small></span>' + icon("right") + '</a><a href="#/markets" data-route="markets"><b>03</b><span><strong>Explore future opportunities</strong><small>Research listed instruments and manage your investment portfolio</small></span>' + icon("right") + '</a></div><div class="note-dot"><i></i>Career and education now connect your weekly choices to employment income and professional progression.</div></article></section>' +
    '<section class="dash-grid lower-grid"><article class="panel">' + panelTitle("Recent activity", "A record of decisions and outcomes.") + emptyState("clock", "Your story has not started yet", "Once a game is running, important actions, settlements and events will be recorded here.", "NO ACTIVITY RECORDED") + '</article><article class="panel principle">' + panelTitle("A principle to remember", "Financial literacy, in context.") + '<blockquote>Wealth is not just what you own. It is also what you owe, what you can access, and what your assets can sustainably produce.</blockquote><label>NETWORTH / FINANCIAL FOUNDATIONS</label></article></section>';
}

export function renderSection(id) {
  const section = sections[id];
  if (!section) return renderOverview();
  const names = { personal: "dossier", finance: "financial records", markets: "market workspace", businesses: "company portfolio", assets: "asset register", network: "relationship network", news: "news feed", reports: "reports" };
  return '<section class="intro"><i>' + icon(section[2]) + '</i><div><label>' + id.toUpperCase() + ' / WORKSPACE</label><h2>' + section[0] + '</h2><p>' + section[1] + '</p></div><span class="ready"><b></b> WORKSPACE READY</span></section>' +
    '<section><div class="section-head"><div><label>WORKSPACE MODULES</label><h2>What lives here</h2></div><span>' + String(section[4].length).padStart(2, "0") + ' MODULES</span></div><div class="features">' + section[4].map(item => featureCard({ title: item[0], description: item[1], icon: item[2] })).join("") + '</div></section>' +
    '<section class="panel">' + panelTitle("No active data", "This section is a navigable Phase 1 placeholder.") + emptyState(section[2], "Your " + names[id] + " will appear here", "The interface is in place. Functional data, interactions and simulation rules are scheduled for " + section[3] + ".", "READY FOR THE NEXT PHASE") + '</section>' +
    '<div class="phase-note">' + icon("check") + '<span><strong>Phase 1 foundation</strong><small>Navigation, layout and empty states are active. No placeholder figures are presented as real simulation data.</small></span></div>';
}
export const getSectionContent = id => sections[id] ?? null;
export const getWorkspaceCount = () => PAGES.length;

import {STARTING_PROFILES,SKILL_KEYS,TIME_KEYS,DEFAULT_TIME_ALLOCATION,WEEKLY_TIME_BUDGET} from "./simulation-core.js";
import {JOB_MARKET,EDUCATION_PROGRAMS,getJobOfferChance} from "./career.js";
const skillLabels={financialLiteracy:"Financial literacy",negotiation:"Negotiation",management:"Management",sales:"Sales",technical:"Technical expertise",research:"Research",leadership:"Leadership",networking:"Networking",operations:"Operations"};
const wellbeingLabels={health:"Health",energy:"Energy",stress:"Stress",happiness:"Happiness"};
const hourLabels={work:"Work",study:"Study",rest:"Rest & recovery",family:"Family",networking:"Networking",research:"Research",sideWork:"Side work",recreation:"Recreation"};
const metricOptions=[...SKILL_KEYS.map(key=>({value:`skill:${key}`,label:`Skill · ${skillLabels[key]}`})),...["health","energy","stress","happiness"].map(key=>({value:`wellbeing:${key}`,label:`Well-being · ${wellbeingLabels[key]}`})),{value:"turns:turn",label:"Milestone · Reach a future turn"}];
function profilePreview(profile){return `<div class="profile-preview-grid"><div><small>EDUCATION</small><b>${profile.education}</b></div><div><small>EXPERIENCE</small><b>${profile.experienceYears} years</b></div><div><small>EMPLOYMENT</small><b>${profile.employment}</b></div><div><small>DEPENDENTS</small><b>${profile.dependents}</b></div><div><small>STARTING CAPITAL CONTEXT</small><b>${profile.startingCapital.toLocaleString("en-US")}</b></div><div><small>STARTING DEBT CONTEXT</small><b>${profile.startingDebt.toLocaleString("en-US")}</b></div><div><small>MONTHLY EXPENSE CONTEXT</small><b>${profile.monthlyExpenseContext.toLocaleString("en-US")}</b></div><div><small>INITIAL WELL-BEING</small><b>Health ${profile.health} · Energy ${profile.energy}</b></div></div>`;}
function renderProfileCreation(){
 return `<section class="panel character-create"><div class="life-section-head"><div><label>CREATE YOUR CHARACTER</label><h2>Choose the life you begin with.</h2><p>Each background changes your education, experience, starting resources, obligations, skills and well-being.</p></div><span class="phase-chip">ONE CHARACTER PER SAVE</span></div><form id="characterForm" class="character-form"><div class="character-fields"><label>CHARACTER NAME<input name="name" minlength="2" maxlength="40" placeholder="Enter a name" required></label><label>AGE<input name="age" type="number" min="18" max="80" value="25" required></label></div><label class="profile-select-label">STARTING PROFILE<select name="profileId" id="profileSelect">${STARTING_PROFILES.map((profile,index)=>`<option value="${profile.id}" ${index===0?"selected":""}>${profile.name}</option>`).join("")}</select></label><p class="profile-tagline" id="profileTagline">${STARTING_PROFILES[0].tagline}</p><div id="profilePreview">${profilePreview(STARTING_PROFILES[0])}</div><button class="primary-button" type="submit">Create character ${icon("arrow")}</button></form></section>`;
}
function renderWellbeing(stats){
 return `<section class="panel"><div class="life-section-head"><div><label>PERSONAL CONDITION</label><h2>Well-being</h2><p>Your weekly choices influence how you feel and perform over time.</p></div></div><div class="wellbeing-grid">${Object.entries(wellbeingLabels).map(([key,label])=>{const value=stats[key];const risk=key==="stress"?value>=70:value<=35;return `<div class="wellbeing-item"><div><span>${label}</span><b>${value}/100</b></div><div class="meter ${risk?"risk":""}"><i style="width:${value}%"></i></div></div>`;}).join("")}</div></section>`;
}
function renderSkills(skills){
 return `<section class="panel"><div class="life-section-head"><div><label>CAPABILITIES</label><h2>Skills & development</h2><p>Study, research, networking and side work build relevant capabilities gradually.</p></div></div><div class="skill-grid">${SKILL_KEYS.map(key=>`<div class="skill-item"><div><span>${skillLabels[key]}</span><b>${skills[key].toFixed(1)}</b></div><div class="meter"><i style="width:${skills[key]}%"></i></div></div>`).join("")}</div></section>`;
}
function renderTimePlanner(allocation){
 const values=allocation??DEFAULT_TIME_ALLOCATION,total=TIME_KEYS.reduce((sum,key)=>sum+(values[key]??0),0);
 return `<section class="panel"><div class="life-section-head"><div><label>WEEKLY ACTION PLANNER</label><h2>Allocate your time</h2><p>You have ${WEEKLY_TIME_BUDGET} waking hours in a standard week after baseline sleep. Unallocated hours remain flexible.</p></div><span class="time-total" id="timeTotal">${total} / ${WEEKLY_TIME_BUDGET} HRS</span></div><form id="timeAllocationForm"><div class="time-allocation-grid">${TIME_KEYS.map(key=>`<label>${hourLabels[key].toUpperCase()}<span class="hour-input"><input data-time-hour name="${key}" type="number" min="0" max="${WEEKLY_TIME_BUDGET}" step="1" value="${values[key]??0}" required><small>HRS / WK</small></span></label>`).join("")}</div><label class="focus-select">STUDY FOCUS<select name="studyFocus">${SKILL_KEYS.map(key=>`<option value="${key}" ${values.studyFocus===key?"selected":""}>${skillLabels[key]}</option>`).join("")}</select></label><p class="allocation-note" id="allocationNote">${WEEKLY_TIME_BUDGET-total} hours remain unallocated. Going beyond the weekly limit is not allowed.</p><button class="primary-button" type="submit">Save weekly plan ${icon("arrow")}</button></form></section>`;
}
function renderGoals(goals,character,turn){
 return `<section class="panel"><div class="life-section-head"><div><label>PERSONAL MILESTONES</label><h2>Goals</h2><p>Set measurable targets and see them update as your character develops.</p></div><span class="phase-chip">${goals.filter(goal=>goal.status==="completed").length} COMPLETED</span></div><form id="goalForm" class="goal-form"><label>GOAL TITLE<input name="title" maxlength="40" minlength="2" placeholder="e.g. Improve financial literacy" required></label><label>MEASURE<select name="metric">${metricOptions.map(item=>`<option value="${item.value}">${item.label}</option>`).join("")}</select></label><label>TARGET<input name="target" type="number" min="1" max="100" value="50" required></label><button class="primary-button" type="submit">Add goal</button></form><div class="goal-list">${goals.length?goals.map(goal=>{const label=metricOptions.find(item=>item.value===goal.metric)?.label??goal.metric;const [kind,key]=goal.metric.split(":");const current=kind==="skill"?character.skills[key]:kind==="wellbeing"?character.wellbeing[key]:turn;const met=goal.metric==="wellbeing:stress"?current<=goal.target:current>=goal.target;const progress=goal.metric==="wellbeing:stress"?Math.min(100,Math.max(0,(100-current)/(100-goal.target||1)*100)):Math.min(100,Math.max(0,current/goal.target*100));return `<article class="goal-item ${goal.status==="completed"?"completed":""}"><div class="goal-copy"><b>${esc(goal.title)}</b><small>${esc(label)} · TARGET ${goal.metric==="wellbeing:stress"?"≤":"≥"} ${goal.target}${goal.metric==="turns:turn"?"":" / 100"} · CURRENT ${Number(current).toFixed(1)}</small><div class="meter"><i style="width:${goal.status==="completed"?100:progress}%"></i></div></div><span>${goal.status==="completed"||met?"COMPLETED":"IN PROGRESS"}</span></article>`;}).join(""):`<p class="goal-empty">No goals yet. Add a target that matters to your character.</p>`}</div></section>`;
}

const moneyLabel=value=>(value/100).toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2});
function renderCareerPanel(career,character,finance,turn){
 const active=career.currentJob,cash=finance?.accounts?.find(a=>a.id==="cash")?.balanceMinor??0;
 const offers=career.applications.filter(a=>a.status==="offered");
 const activeCourse=career.activeCourse;
 const jobs=JOB_MARKET.map(job=>{
  const application=career.applications.find(a=>a.jobId===job.id),chance=getJobOfferChance(job.id,character,career);
  const cooling=application&&turn-application.appliedAtTurn<4&&application.status==="rejected";
  const status=application?.status==="offered"?"OFFER RECEIVED":application?.status==="accepted"?"ACCEPTED":application?.status==="rejected"?"RECENTLY DECLINED":application?.status==="closed"?"CLOSED":"OPEN";
  return `<article class="career-card"><div class="career-card-top"><span>${esc(job.level.toUpperCase())} · ${esc(job.industry.toUpperCase())}</span><b>${status}</b></div><h3>${esc(job.title)}</h3><p>${esc(job.employer)}</p><div class="career-card-stats"><div><small>WEEKLY PAY</small><strong>${moneyLabel(job.weeklyPayMinor)}</strong></div><div><small>HOURS / WEEK</small><strong>${job.hoursPerWeek} hrs</strong></div></div><div class="career-requirements"><small>REQUIREMENTS</small><span>Education level ${job.requiredEducation}+ · ${job.requiredExperience}+ years' experience</span><span>${Object.entries(job.requiredSkills).map(([key,value])=>`${skillLabels[key]} ${value}+`).join(" · ")}</span></div><div class="career-fit"><span>ESTIMATED OFFER CHANCE</span><b>${chance}%</b></div><button class="primary-button" data-career-action="APPLY_FOR_JOB" data-job-id="${job.id}" ${active&&active.jobId===job.id?"disabled":""} ${application?.status==="offered"||application?.status==="accepted"||cooling?"disabled":""}>${application?.status==="offered"?"Offer available below":application?.status==="accepted"?"Currently employed":cooling?"Reapply in "+(4-(turn-application.appliedAtTurn))+" turns":"Apply for position"}</button></article>`;
 }).join("");
 const courseCards=EDUCATION_PROGRAMS.map(course=>{
  const complete=career.completedCourses.includes(course.id),prerequisite=course.prerequisite&&!career.completedCourses.includes(course.prerequisite),eligible=career.educationLevel>=course.requiredEducation&&!prerequisite&&cash>=course.tuitionMinor&&!activeCourse&&!complete;
  return `<article class="education-card"><div class="career-card-top"><span>FORMAL EDUCATION</span><b>${complete?"COMPLETED":course.durationWeeks+" WEEKS"}</b></div><h3>${esc(course.title)}</h3><p>${esc(course.provider)}</p><div class="education-details"><div><small>TUITION</small><strong>${moneyLabel(course.tuitionMinor)} Credits</strong></div><div><small>STUDY COMMITMENT</small><strong>${course.studyHoursPerWeek} hrs / week</strong></div></div><p class="education-award">Award: ${esc(course.award)}</p>${prerequisite?`<small class="education-lock">Prerequisite: ${esc(EDUCATION_PROGRAMS.find(x=>x.id===course.prerequisite)?.title??course.prerequisite)}</small>`:!complete&&career.educationLevel<course.requiredEducation?`<small class="education-lock">Requires education level ${course.requiredEducation}</small>`:!complete&&cash<course.tuitionMinor?`<small class="education-lock">Insufficient cash for tuition</small>`:""}<button class="primary-button" data-career-action="ENROLL_COURSE" data-course-id="${course.id}" ${eligible?"":"disabled"}>${complete?"Completed":activeCourse?"Finish current program first":"Enroll · "+moneyLabel(course.tuitionMinor)+" Credits"}</button></article>`;
 }).join("");
 const current=active?`<div class="active-career"><div><label>ACTIVE EMPLOYMENT</label><h3>${esc(active.title)} ${active.level>1?"· LEVEL "+active.level:""}</h3><p>${esc(active.employer)} · ${esc(active.industry)}</p></div><div class="active-career-stats"><span><small>WEEKLY CONTRACT</small><b>${moneyLabel(active.weeklyPayMinor)} Credits</b></span><span><small>ESTIMATED MONTHLY</small><b>${moneyLabel(Math.round(active.weeklyPayMinor*52/12))} Credits</b></span><span><small>CONTRACT HOURS</small><b>${active.hoursPerWeek} hrs / week</b></span><span><small>PERFORMANCE</small><b>${career.performance}/100</b></span><span><small>WEEKS IN ROLE</small><b>${career.weeksEmployed}</b></span><span><small>PROMOTIONS</small><b>${career.promotions}</b></span></div><button class="secondary-button" data-career-action="RESIGN_FROM_JOB">Resign from position</button></div>`:`<div class="career-empty"><b>No active employment contract</b><span>Apply for a role to receive a potential offer. Accepted positions pay weekly through your household ledger.</span></div>`;
 const offerCards=offers.map(offer=>{const job=JOB_MARKET.find(j=>j.id===offer.jobId);return `<div class="offer-row"><div><b>${esc(job.title)} · ${esc(job.employer)}</b><small>${moneyLabel(job.weeklyPayMinor)} Credits / week · ${job.hoursPerWeek} hours</small></div><button class="primary-button" data-career-action="ACCEPT_JOB_OFFER" data-application-id="${offer.id}">Accept offer</button></div>`;}).join("");
 const courseProgress=activeCourse?`<div class="active-course"><div><div><label>IN PROGRESS</label><h3>${esc(activeCourse.title)}</h3><p>${esc(activeCourse.provider)}</p></div><b>${Math.round(activeCourse.progressWeeks/EDUCATION_PROGRAMS.find(c=>c.id===activeCourse.courseId).durationWeeks*100)}%</b></div><div class="meter"><i style="width:${activeCourse.progressWeeks/EDUCATION_PROGRAMS.find(c=>c.id===activeCourse.courseId).durationWeeks*100}%"></i></div><small>Allocate at least ${EDUCATION_PROGRAMS.find(c=>c.id===activeCourse.courseId).studyHoursPerWeek} study hours per week for full progress.</small></div>`:`<div class="career-empty"><b>No active education program</b><span>Enroll in a course to build specialist skills and earn a formal credential. Tuition is charged immediately.</span></div>`;
 return `<section class="panel career-panel"><div class="life-section-head"><div><label>CAREER & EMPLOYMENT</label><h2>Your professional life</h2><p>Apply for opportunities, manage offers and build experience. Work hours determine weekly salary and influence performance.</p></div><span class="phase-chip">PHASE 5</span></div>${current}${offerCards?`<div class="offer-list"><label>OPEN JOB OFFERS</label>${offerCards}</div>`:""}<div class="career-section-head"><div><label>AVAILABLE OPPORTUNITIES</label><h3>Job market</h3><p>Offer chances reflect your skills, education, experience and reputation. Applications use the simulation's seeded random sequence.</p></div><span>${JOB_MARKET.length} LISTINGS</span></div><div class="career-grid">${jobs}</div><div class="career-section-head"><div><label>EDUCATION & QUALIFICATIONS</label><h3>Invest in your capabilities</h3><p>Tuition is charged from available cash. Study hours advance a program; completion awards a credential and may raise your education level.</p></div><span>LEVEL ${career.educationLevel}</span></div><div class="credential-list">${career.credentials.length?career.credentials.map(x=>`<span>${esc(x)}</span>`).join(""):"<small>No additional credentials earned yet.</small>"}</div>${courseProgress}<div class="education-grid">${courseCards}</div><div class="career-history"><label>EMPLOYMENT HISTORY</label>${career.employmentHistory.length?career.employmentHistory.slice().reverse().map(job=>`<div><b>${esc(job.title)} · ${esc(job.employer)}</b><small>Started turn ${job.startedAtTurn} · Ended turn ${job.endedAtTurn} · ${esc(job.endReason)}</small></div>`).join(""):"<small>Your career history will appear here as you move between roles.</small>"}</div><p class="career-feedback" id="careerFeedback" role="status" aria-live="polite"></p></section>`;
}

export function renderPersonalView(state){
 if(!state)return `<section class="panel"><div class="empty"><i>${icon("user")}</i><div><label>SIMULATION REQUIRED</label><h3>Start a game first</h3><p>Create a simulation from Overview, then return here to build your character.</p><a class="primary-button" href="#/overview" data-route="overview">Go to Overview</a></div></div></section>`;
 const character=state.life?.character;
 if(!character)return renderProfileCreation();
 const context=character.startingContext;
 const employmentLabel=state.career?.currentJob?`${state.career.currentJob.title} · ${state.career.currentJob.employer}`:character.employment;
 return `<section class="character-hero panel"><div><label>CHARACTER DOSSIER / ${esc(character.profileName.toUpperCase())}</label><h2>${esc(character.name)}</h2><p>Age ${character.age} · ${esc(character.education)} · ${character.experienceYears} years' experience</p><span>${esc(employmentLabel)}</span></div><div class="character-id"><small>CHARACTER ID</small><b>${esc(character.id)}</b><small>CREATED TURN ${character.createdAtTurn}</small></div></section><section class="panel"><div class="life-section-head"><div><label>STARTING CIRCUMSTANCES</label><h2>Your starting context</h2><p>These opening figures are now represented in your authoritative Finance ledger. Monthly expenses are a planning baseline, not an automatic charge.</p></div></div><div class="profile-preview-grid"><div><small>STARTING CAPITAL CONTEXT</small><b>${context.capital.toLocaleString("en-US")}</b></div><div><small>STARTING DEBT CONTEXT</small><b>${context.debt.toLocaleString("en-US")}</b></div><div><small>MONTHLY EXPENSE CONTEXT</small><b>${context.monthlyExpense.toLocaleString("en-US")}</b></div><div><small>DEPENDENTS</small><b>${context.dependents}</b></div><div><small>REPUTATION</small><b>${character.reputation}/100</b></div><div><small>CONTACTS</small><b>${character.contacts}</b></div></div></section>${renderCareerPanel(state.career,character,state.finance,state.calendar.turn)}${renderWellbeing(character.wellbeing)}${renderSkills(character.skills)}${renderTimePlanner(state.life.timeAllocation)}${renderGoals(state.life.goals,character,state.calendar.turn)}`;
}

export function renderStartingProfilePreview(profileId){const profile=STARTING_PROFILES.find(item=>item.id===profileId)??STARTING_PROFILES[0];return {tagline:profile.tagline,html:profilePreview(profile)};}

const credit = value => (Number(value||0)/100).toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2});
const financeLabels = {cash:"Cash",savings:"Savings",investment:"Investment holdings",loan:"Outstanding debt",income:"Recorded income",expense:"Recorded expenses"};
function financeMetric(label,value,description="CURRENT POSITION"){return `<article class="finance-metric"><small>${label}</small><strong>${credit(value)}</strong><span>${description}</span></article>`;}

function renderBankingPanel(state){
 const b=state.banking,accounts=b.accounts.filter(a=>a.status==="open"),loans=b.loans.filter(x=>x.status==="active"),cards=b.cards.filter(x=>x.status==="open"),fixed=b.fixedDeposits.filter(x=>x.status==="active");
 const institutions=BANKING_INSTITUTIONS.map(x=>`<option value="${x.id}">${esc(x.name)} · ${esc(x.type)}</option>`).join("");
 const accountOptions=accounts.map(x=>`<option value="${x.id}">${esc(BANKING_INSTITUTIONS.find(y=>y.id===x.bankId).name)} — ${esc(x.type)} (${credit(x.balanceMinor)})</option>`).join("");
 const loanOptions=loans.map(x=>`<option value="${x.id}">${esc(x.type)} · ${esc(BANKING_INSTITUTIONS.find(y=>y.id===x.bankId).name)} (due ${credit(x.paymentMinor)}/week)</option>`).join("");
 const cardOptions=cards.map(x=>`<option value="${x.id}">${esc(BANKING_INSTITUTIONS.find(y=>y.id===x.bankId).name)} (balance ${credit(x.balanceMinor)} / ${credit(x.limitMinor)})</option>`).join("");
 const accountRows=accounts.map(x=>`<tr><td><b>${esc(BANKING_INSTITUTIONS.find(y=>y.id===x.bankId).name)}</b><small>${esc(x.type.toUpperCase())} · ${esc(x.id)}</small></td><td class="money">${credit(x.balanceMinor)}</td><td>${x.type==="savings"?"Variable interest":"Payment access"}</td></tr>`).join("");
 const loanRows=b.loans.map(x=>`<tr><td><b>${esc(x.type.toUpperCase())} · ${esc(BANKING_INSTITUTIONS.find(y=>y.id===x.bankId).name)}</b><small>${esc(x.status.toUpperCase())} · ${x.rateBps/100}% APR · ${x.termWeeks} weeks</small></td><td class="money">${credit(x.principalMinor+x.interestAccruedMinor)}</td><td class="money">${credit(x.paymentMinor)}</td><td>${x.missedPayments} missed</td></tr>`).join("");
 const fixedRows=fixed.map(x=>`<tr><td>${esc(BANKING_INSTITUTIONS.find(y=>y.id===x.bankId).name)}</td><td class="money">${credit(x.principalMinor)}</td><td class="money">${credit(x.interestMinor)}</td><td>Turn ${x.maturityTurn}</td></tr>`).join("");
 const cardRows=cards.map(x=>`<tr><td>${esc(BANKING_INSTITUTIONS.find(y=>y.id===x.bankId).name)}</td><td class="money">${credit(x.balanceMinor)}</td><td class="money">${credit(x.limitMinor)}</td><td>${x.rateBps/100}% APR</td></tr>`).join("");
 const loanTypes=Object.entries(getLoanTypes()).map(([id,x])=>`<option value="${id}">${esc(x.label)} · max ${x.maxTerm} weeks</option>`).join("");
 const bankCards=BANKING_INSTITUTIONS.map(x=>`<article class="bank-institution"><div><span>${esc(x.type.toUpperCase())}</span><b>${x.stability}/100 STABILITY</b></div><h3>${esc(x.name)}</h3><p>${esc(x.description)}</p><div><small>DEPOSIT RATE</small><strong>${(x.depositRateBps/100).toFixed(2)}% APR</strong><small>LOAN RATE</small><strong>${(x.loanRateBps/100).toFixed(2)}% APR</strong></div><small>${x.depositInsurance?"Insured deposits up to "+credit(x.insuranceCoverageMinor)+" Credits":"No deposit insurance"} · Fee ${credit(x.feeMinor)} Credits / week</small></article>`).join("");
 return `<section class="panel banking-panel"><div class="life-section-head"><div><label>PHASE 6 / BANKING & CREDIT</label><h2>Financial institutions</h2><p>Compare providers before opening accounts or taking credit. Rates and institutions are fictional simulation data, not real-world offers.</p></div><span class="phase-chip">CREDIT SCORE ${b.creditScore} / 850</span></div><div class="credit-score-panel"><div><small>SIMULATED CREDIT SCORE</small><strong>${b.creditScore}</strong><span>300–579 Poor · 580–669 Fair · 670–739 Good · 740–799 Very good · 800–850 Excellent</span></div><div><small>OPEN DEPOSIT ACCOUNTS</small><strong>${accounts.length}</strong></div><div><small>ACTIVE CREDIT</small><strong>${loans.length+cards.length}</strong></div><div><small>FIXED DEPOSITS</small><strong>${fixed.length}</strong></div></div><div class="bank-institution-grid">${bankCards}</div></section>
 <section class="panel banking-panel"><div class="life-section-head"><div><label>DEPOSIT PRODUCTS</label><h2>Checking, savings & fixed deposits</h2><p>Opening a bank account transfers funds from available cash into a dedicated balance-sheet asset. Interest is credited through the ledger.</p></div></div><div class="banking-form-grid">
 <form class="finance-form" data-banking-form="OPEN_BANK_ACCOUNT"><h3>Open a bank account</h3><label>Institution<select name="bankId">${institutions}</select></label><label>Account type<select name="accountType"><option value="checking">Checking</option><option value="savings">Savings</option></select></label><label>Opening deposit<input name="amount" inputmode="decimal" placeholder="0.00" required></label><button class="primary-button">Open account</button></form>
 <form class="finance-form" data-banking-form="CREATE_FIXED_DEPOSIT"><h3>Create fixed deposit</h3><label>Fund from account<select name="accountId">${accountOptions}</select></label><label>Amount<input name="amount" inputmode="decimal" placeholder="0.00" required></label><label>Term<select name="termWeeks"><option value="4">4 weeks</option><option value="8">8 weeks</option><option value="12">12 weeks</option><option value="26">26 weeks</option><option value="52">52 weeks</option></select></label><button class="primary-button" ${accounts.length?"":"disabled"}>Lock fixed deposit</button></form>
 <form class="finance-form" data-banking-form="WITHDRAW_BANK_FUNDS"><h3>Withdraw to cash</h3><label>Bank account<select name="accountId">${accountOptions}</select></label><label>Amount<input name="amount" inputmode="decimal" placeholder="0.00" required></label><button class="primary-button" ${accounts.length?"":"disabled"}>Withdraw funds</button></form></div><div class="table-wrap"><table class="finance-table"><thead><tr><th>ACCOUNT</th><th class="money">BALANCE</th><th>FEATURE</th></tr></thead><tbody>${accountRows||'<tr><td colspan="3">No bank accounts opened yet.</td></tr>'}</tbody></table></div><div class="table-wrap"><table class="finance-table"><thead><tr><th>FIXED DEPOSIT</th><th class="money">PRINCIPAL</th><th class="money">EXPECTED INTEREST</th><th>MATURITY</th></tr></thead><tbody>${fixedRows||'<tr><td colspan="4">No active fixed deposits.</td></tr>'}</tbody></table></div></section>
 <section class="panel banking-panel"><div class="life-section-head"><div><label>LENDING & CREDIT</label><h2>Loans and credit facilities</h2><p>Credit eligibility depends on score, product limits and income. Secured loans require a collateral description. Loan principal is a liability, not income.</p></div></div><div class="banking-form-grid">
 <form class="finance-form" data-banking-form="APPLY_FOR_LOAN"><h3>Apply for a loan</h3><label>Lender<select name="bankId">${institutions}</select></label><label>Product<select name="loanType">${loanTypes}</select></label><label>Amount<input name="amount" inputmode="decimal" placeholder="0.00" required></label><label>Term (weeks)<input name="termWeeks" type="number" min="1" max="260" value="52" required></label><label>Collateral (secured loans)<input name="collateral" maxlength="80" placeholder="e.g. Residential property"></label><button class="primary-button">Submit loan application</button></form>
 <form class="finance-form" data-banking-form="APPLY_FOR_CREDIT_CARD"><h3>Request a credit card</h3><label>Issuer<select name="bankId">${institutions}</select></label><label>Credit limit<input name="limit" inputmode="decimal" placeholder="0.00" required></label><button class="primary-button">Apply for card</button></form>
 <form class="finance-form" data-banking-form="PAY_LOAN_INSTALLMENT"><h3>Make a loan payment</h3><label>Loan<select name="loanId">${loanOptions}</select></label><label>Payment amount<input name="amount" inputmode="decimal" placeholder="0.00" required></label><button class="primary-button" ${loans.length?"":"disabled"}>Pay loan</button></form>
 <form class="finance-form" data-banking-form="USE_CREDIT_CARD"><h3>Use credit card</h3><label>Card<select name="cardId">${cardOptions}</select></label><label>Purchase amount<input name="amount" inputmode="decimal" placeholder="0.00" required></label><button class="primary-button" ${cards.length?"":"disabled"}>Make purchase</button></form>
 <form class="finance-form" data-banking-form="PAY_CREDIT_CARD"><h3>Pay credit card</h3><label>Card<select name="cardId">${cardOptions}</select></label><label>Payment amount<input name="amount" inputmode="decimal" placeholder="0.00" required></label><button class="primary-button" ${cards.length?"":"disabled"}>Pay card balance</button></form></div>
 <div class="table-wrap"><table class="finance-table"><thead><tr><th>LOAN / STATUS</th><th class="money">BALANCE</th><th class="money">WEEKLY PAYMENT</th><th>PAYMENT RECORD</th></tr></thead><tbody>${loanRows||'<tr><td colspan="4">No loans yet.</td></tr>'}</tbody></table></div>
 <div class="table-wrap"><table class="finance-table"><thead><tr><th>CREDIT CARD</th><th class="money">BALANCE</th><th class="money">LIMIT</th><th>APR</th></tr></thead><tbody>${cardRows||'<tr><td colspan="4">No credit cards yet.</td></tr>'}</tbody></table></div>
 <p class="banking-feedback" id="bankingFeedback" role="status" aria-live="polite"></p></section>`;
}
export function renderFinanceView(state){
 if(!state)return `<section class="panel"><div class="empty"><i>${icon("wallet")}</i><div><label>SIMULATION REQUIRED</label><h3>Start a game first</h3><p>Create a simulation from Overview, then build your character to initialize the household ledger.</p><a class="primary-button" href="#/overview" data-route="overview">Go to Overview</a></div></div></section>`;
 if(!state.life?.character||!state.finance)return `<section class="panel"><div class="empty"><i>${icon("wallet")}</i><div><label>CHARACTER REQUIRED</label><h3>Create your character first</h3><p>Your profile determines opening cash, debt and the initial household budget. These become ledger records when your character is created.</p><a class="primary-button" href="#/personal" data-route="personal">Create character</a></div></div></section>`;
 const f=state.finance,s=getFinanceSummary(f),accounts=f.accounts.filter(a=>["asset","liability"].includes(a.type));
 const accountRows=accounts.map(a=>`<tr><td>${esc(a.name)}</td><td>${esc(a.type.toUpperCase())}</td><td class="money">${credit(a.balanceMinor)}</td></tr>`).join("");
 const budgets=f.budgets.map(b=>`<div class="budget-row"><div><b>${esc(b.label)}</b><small>${esc(b.category)} · MONTHLY LIMIT</small></div><strong>${credit(b.monthlyLimitMinor)}</strong></div>`).join("");
 const ledger=f.ledger.slice().reverse().slice(0,30).map(e=>`<tr><td>${esc(e.date)}</td><td><b>${esc(e.description)}</b><small>${esc(e.kind.replaceAll("_"," "))}</small></td><td class="money">${credit(e.amountMinor)}</td></tr>`).join("");
 return `<section class="finance-summary-grid">${financeMetric("AVAILABLE CASH",s.cash)}${financeMetric("NET WORTH",s.netWorth,"ASSETS LESS LIABILITIES")}${financeMetric("MONTHLY BASELINE",s.monthlyBaseline,"PLANNING CONTEXT")}${financeMetric("OUTSTANDING DEBT",s.liabilities)}</section>
 <section class="panel"><div class="life-section-head"><div><label>HOUSEHOLD BALANCE SHEET</label><h2>Accounts & position</h2><p>Balances are derived from posted journal entries. Currency unit: ${CURRENCY_LABEL}. Transfers and loan principal are not income.</p></div><span class="phase-chip">DOUBLE-ENTRY LEDGER</span></div><div class="finance-metrics-inline"><div><small>LIQUID NET WORTH</small><b>${credit(s.liquidNetWorth)}</b></div><div><small>ASSETS</small><b>${credit(s.assets)}</b></div><div><small>LIABILITIES</small><b>${credit(s.liabilities)}</b></div><div><small>RECORDED NET CASH FLOW</small><b>${credit(s.netCashflow)}</b></div></div><div class="table-wrap"><table class="finance-table"><thead><tr><th>ACCOUNT</th><th>TYPE</th><th class="money">BALANCE (${CURRENCY_LABEL.toUpperCase()})</th></tr></thead><tbody>${accountRows}</tbody></table></div></section>
 <section class="panel"><div class="life-section-head"><div><label>RECORD A DECISION</label><h2>Household transactions</h2><p>Each action posts a balanced journal entry. Amounts accept up to two decimal places.</p></div></div><div class="finance-action-grid">
 <form class="finance-form" data-finance-form="RECORD_INCOME"><h3>Record income</h3><label>Amount<input name="amount" inputmode="decimal" placeholder="0.00" required></label><label>Description<input name="description" maxlength="80" placeholder="e.g. Other income"></label><button class="primary-button">Post income</button></form>
 <form class="finance-form" data-finance-form="RECORD_EXPENSE"><h3>Record expense</h3><label>Amount<input name="amount" inputmode="decimal" placeholder="0.00" required></label><label>Description<input name="description" maxlength="80" placeholder="e.g. Household purchase"></label><button class="primary-button">Post expense</button></form>
 <form class="finance-form" data-finance-form="TRANSFER_FUNDS"><h3>Transfer between accounts</h3><label>Amount<input name="amount" inputmode="decimal" placeholder="0.00" required></label><div class="finance-selects"><label>From<select name="from"><option value="cash">Cash</option><option value="savings">Savings</option></select></label><label>To<select name="to"><option value="savings">Savings</option><option value="cash">Cash</option></select></label></div><button class="primary-button">Transfer funds</button></form>
 <form class="finance-form" data-finance-form="BORROW_MONEY"><h3>Borrow money</h3><label>Amount<input name="amount" inputmode="decimal" placeholder="0.00" required></label><label>Description<input name="description" maxlength="80" placeholder="e.g. Personal loan"></label><button class="primary-button">Record borrowing</button></form>
 <form class="finance-form" data-finance-form="REPAY_DEBT"><h3>Repay loan principal</h3><label>Amount<input name="amount" inputmode="decimal" placeholder="0.00" required></label><label>Description<input name="description" maxlength="80" placeholder="Principal repayment"></label><button class="primary-button">Repay principal</button></form>
 <article class="finance-form"><h3>Investment holdings</h3><p>Buy and sell market instruments, monitor portfolio value and review realized or unrealized returns in the Markets workspace.</p><a class="primary-button" href="#/markets" data-route="markets">Open Markets</a></article>
 </div><p class="game-feedback" id="financeFeedback" role="status" aria-live="polite"></p></section>
 <section class="finance-bottom-grid"><article class="panel"><div class="life-section-head"><div><label>SPENDING PLAN</label><h2>Monthly budgets</h2><p>Budget limits are planning controls; they do not create transactions.</p></div></div><form class="budget-form" data-finance-form="SET_BUDGET"><label>Category<select name="category"><option value="household">Household</option><option value="transport">Transport</option><option value="education">Education</option><option value="health">Health</option><option value="leisure">Leisure</option><option value="other">Other</option></select></label><label>Monthly limit<input name="amount" inputmode="decimal" placeholder="0.00" required></label><button class="primary-button">Save budget</button></form><div class="budget-list">${budgets}</div></article><article class="panel"><div class="life-section-head"><div><label>CASH FLOW</label><h2>Recorded activity</h2><p>Only posted income and expenses affect net cash flow. Transfers, borrowing and valuation changes are excluded.</p></div></div><div class="finance-cashflow"><div><small>INCOME</small><b>${credit(s.income)}</b></div><div><small>EXPENSES</small><b>${credit(s.expenses)}</b></div><div><small>NET</small><b>${credit(s.netCashflow)}</b></div></div></article></section>
 <section class="panel"><div class="life-section-head"><div><label>IMMUTABLE POSTED HISTORY</label><h2>Journal</h2><p>Entries are append-only in this phase. Corrections will use reversal entries rather than editing posted history.</p></div><span class="phase-chip">${f.ledger.length} ENTRIES</span></div><div class="table-wrap"><table class="finance-table"><thead><tr><th>DATE</th><th>DESCRIPTION</th><th class="money">AMOUNT</th></tr></thead><tbody>${ledger||'<tr><td colspan="3">No entries yet.</td></tr>'}</tbody></table></div></section>` + renderBankingPanel(state);
}


export function renderMarketsView(state){
 if(!state||!state.life?.character||!state.markets)return `<section class="panel">${emptyState("chart","Start a simulation to access the markets","Create a character to initialize the investment exchange and portfolio.","SIMULATION REQUIRED")}<a class="primary-button" href="#/overview" data-route="overview">Go to Overview</a></section>`;
 const m=state.markets,portfolio=getMarketPortfolio(m),cash=state.finance.accounts.find(x=>x.id==="cash")?.balanceMinor??0;
 const fmt=moneyLabel,pct=n=>(n/100).toFixed(2)+"%",kindLabel=k=>({"equity":"Equity","government-bond":"Government bond","corporate-bond":"Corporate bond","commodity":"Commodity","crypto":"Digital asset"}[k]||k);
 const securities=m.securities.map(s=>{const delta=s.priceMinor-s.previousPriceMinor,change=s.previousPriceMinor?delta/s.previousPriceMinor*100:0,held=m.positions.find(p=>p.securityId===s.id),watch=m.watchlist.includes(s.id);return `<article class="market-security"><div class="market-security-top"><span>${esc(kindLabel(s.kind).toUpperCase())} · ${esc(s.sector.toUpperCase())}</span><button type="button" class="watch-toggle ${watch?"active":""}" data-market-watch="${s.id}" aria-label="${watch?"Remove from":"Add to"} watchlist">${watch?"★":"☆"}</button></div><div class="market-security-title"><div><h3>${esc(s.name)}</h3><b>${esc(s.symbol)}</b></div><strong>${fmt(s.priceMinor)}</strong></div><div class="market-change ${delta>=0?"positive":"negative"}">${delta>=0?"+":""}${fmt(delta)} Credits · ${change>=0?"+":""}${change.toFixed(2)}% this week</div><p>${esc(s.description)}</p><div class="market-security-meta"><span>RISK <b>${esc(s.risk)}</b></span><span>YIELD <b>${pct(s.yieldBps)} APR</b></span><span>RESEARCH <b>${s.quality}/100</b></span></div><div class="market-sparkline"><svg viewBox="0 0 120 28" role="img" aria-label="Recent price history"><polyline fill="none" stroke="${delta>=0?"#5d9875":"#b87969"}" stroke-width="2" points="${s.history.map((p,i)=>`${s.history.length<2?60:i*120/(s.history.length-1)},${26-(p-Math.min(...s.history))/(Math.max(...s.history)-Math.min(...s.history)||1)*22}`).join(" ")}"/></svg><small>LAST ${s.history.length} WEEKLY OBSERVATIONS</small></div><div class="market-security-bottom"><span>${held?"HELD · "+(held.quantityUnits/10000).toFixed(4)+" UNITS":"NOT IN PORTFOLIO"}</span><button type="button" class="text-button" data-market-select="${s.id}">Trade instrument</button></div></article>`;}).join("");
 const positions=m.positions.map(p=>{const s=m.securities.find(x=>x.id===p.securityId),ret=p.costBasisMinor?p.unrealizedMinor/p.costBasisMinor*100:0;return `<tr><td><b>${esc(s.name)}</b><small>${esc(s.symbol)} · ${(p.quantityUnits/10000).toFixed(4)} units</small></td><td class="money">${fmt(p.costBasisMinor)}</td><td class="money">${fmt(p.marketValueMinor)}</td><td class="money ${p.unrealizedMinor>=0?"positive":"negative"}">${p.unrealizedMinor>=0?"+":""}${fmt(p.unrealizedMinor)}<small>${ret>=0?"+":""}${ret.toFixed(2)}%</small></td></tr>`;}).join("");
 const tx=m.transactions.slice(0,12).map(t=>`<tr><td>${esc(t.date)}</td><td><b>${esc(t.description)}</b><small>${esc(t.kind)}</small></td><td class="money">${fmt(t.amountMinor)}</td></tr>`).join("");
 const selected=m.securities[0]?.id??"";
 return `<section class="market-overview-grid"><article class="market-overview-card"><small>PORTFOLIO MARKET VALUE</small><strong>${fmt(portfolio.value)}</strong><span>${portfolio.positions} open positions</span></article><article class="market-overview-card"><small>INVESTED COST BASIS</small><strong>${fmt(portfolio.cost)}</strong><span>Capital deployed</span></article><article class="market-overview-card"><small>UNREALIZED RETURN</small><strong class="${portfolio.unrealized>=0?"positive":"negative"}">${portfolio.unrealized>=0?"+":""}${fmt(portfolio.unrealized)}</strong><span>${portfolio.cost?(portfolio.unrealized/portfolio.cost*100).toFixed(2):"0.00"}% return on cost</span></article><article class="market-overview-card"><small>AVAILABLE CASH</small><strong>${fmt(cash)}</strong><span>Trading fee: 0.15% per order</span></article></section>
 <section class="panel market-index-panel"><div><label>MARKET CONDITIONS / TURN ${m.turn}</label><h2>Market index <strong>${(m.marketIndex/100).toFixed(2)}</strong></h2><p>Simulated market regime: <b>${esc(m.regime)}</b> · Sentiment ${m.sentiment>=0?"+":""}${m.sentiment}</p></div><span class="phase-chip">DETERMINISTIC MARKET MODEL</span></section>
 <section class="panel market-trading-panel"><div class="life-section-head"><div><label>ORDER TERMINAL</label><h2>Place a market order</h2><p>Orders execute at the current simulated price. Units can be fractional to four decimal places. A 0.15% trading fee is charged separately.</p></div></div><form class="market-order-form" data-market-form><label>Instrument<select name="securityId">${m.securities.map(s=>`<option value="${s.id}" ${s.id===selected?"selected":""}>${esc(s.symbol)} — ${esc(s.name)} (${fmt(s.priceMinor)} Credits)</option>`).join("")}</select></label><label>Quantity<input name="quantity" inputmode="decimal" placeholder="e.g. 1.2500" value="1" required></label><div class="market-order-buttons"><button class="primary-button" type="submit" name="order" value="MARKET_BUY">Buy</button><button class="secondary-button" type="submit" name="order" value="MARKET_SELL">Sell</button></div><small>Available cash: ${fmt(cash)} Credits. Purchases are rejected if cash cannot cover principal and fees.</small><p class="market-feedback" id="marketFeedback" role="status" aria-live="polite"></p></form></section>
 <section class="panel"><div class="life-section-head"><div><label>INVESTMENT UNIVERSE</label><h2>Market instruments</h2><p>Fictional equities, government and corporate bonds, commodity benchmarks and digital assets. Price movement is simulated each weekly turn.</p></div><span class="phase-chip">${m.securities.length} LISTED</span></div><div class="market-security-grid">${securities}</div></section>
 <section class="panel"><div class="life-section-head"><div><label>YOUR CAPITAL</label><h2>Portfolio holdings</h2><p>Unrealized gains and losses change asset valuation and net worth, not cash flow. Realized returns are recognized when positions are sold.</p></div></div><div class="table-wrap"><table class="finance-table"><thead><tr><th>POSITION</th><th class="money">COST BASIS</th><th class="money">MARKET VALUE</th><th class="money">UNREALIZED P/L</th></tr></thead><tbody>${positions||'<tr><td colspan="4">No investment positions yet. Research an instrument and place your first order.</td></tr>'}</tbody></table></div></section>
 <section class="panel"><div class="life-section-head"><div><label>ORDER HISTORY</label><h2>Recent market transactions</h2><p>Trade activity is retained in the market subledger and the general financial journal.</p></div></div><div class="table-wrap"><table class="finance-table"><thead><tr><th>DATE</th><th>TRANSACTION</th><th class="money">GROSS VALUE</th></tr></thead><tbody>${tx||'<tr><td colspan="3">No market orders have been placed.</td></tr>'}</tbody></table></div></section>`;
}


export function renderAssetsView(state) {
  if (!state || !state.life?.character || !state.assets) return '<section class="panel">' + emptyState("gem", "Start a simulation to manage assets", "Create a character to open the property and collectibles portfolio.", "SIMULATION REQUIRED") + '<a class="primary-button" href="#/overview" data-route="overview">Go to Overview</a></section>';

  const a = state.assets, portfolio = getAssetPortfolio(a);
  const propertiesOwned = new Set(a.properties.map(item => item.listingId));
  const collectiblesOwned = new Set(a.collectibles.map(item => item.catalogId));
  const mortgageFor = property => property.mortgageId ? state.banking.loans.find(item => item.id === property.mortgageId) : null;
  const propertyCards = PROPERTY_LISTINGS.map(listing => {
    const owned = propertiesOwned.has(listing.id);
    const down = Math.round(listing.priceMinor * 0.2);
    const closing = Math.ceil(listing.priceMinor * 150 / 10000);
    return '<article class="asset-catalog-card"><div class="asset-card-top"><span>' + esc(listing.type.toUpperCase()) + '</span><b>' + esc(listing.risk.toUpperCase()) + '</b></div><h3>' + esc(listing.name) + '</h3><p>' + esc(listing.description) + '</p><div class="asset-price">' + moneyLabel(listing.priceMinor) + ' <small>Credits · indicative asking price</small></div><div class="asset-detail-grid"><div><small>EST. WEEKLY RENT</small><b>' + moneyLabel(listing.weeklyRentMinor) + '</b></div><div><small>WEEKLY UPKEEP</small><b>' + moneyLabel(listing.weeklyMaintenanceMinor) + '</b></div><div><small>ANNUAL PROPERTY TAX</small><b>' + (listing.annualTaxBps / 100).toFixed(2) + '%</b></div><div><small>20% DOWN + CLOSING</small><b>' + moneyLabel(down + closing) + '</b></div></div>' +
      (owned ? '<div class="asset-owned-label">ALREADY IN YOUR PORTFOLIO</div>' : '<form class="asset-purchase-form" data-asset-form="ASSET_BUY_PROPERTY"><input type="hidden" name="listingId" value="' + listing.id + '"><label>Property use<select name="use"><option value="rental">Rental investment</option><option value="owner-occupied">Owner-occupied</option></select></label><label>Down payment<select name="downPaymentBps"><option value="2000">20%</option><option value="2500">25%</option><option value="3000">30%</option><option value="4000">40%</option><option value="5000">50%</option><option value="10000">100% · no mortgage</option></select></label><button class="primary-button" type="submit">Acquire property</button></form>') + '</article>';
  }).join("");

  const ownedProperties = a.properties.map(property => {
    const loan = mortgageFor(property), debt = loan && loan.status === "active" ? loan.principalMinor + loan.interestAccruedMinor : 0;
    const equity = property.marketValueMinor - debt;
    return '<article class="asset-holding-card"><div class="asset-card-top"><span>' + esc(property.type.toUpperCase()) + '</span><b>' + (property.use === "rental" ? (property.occupied ? "TENANTED" : "VACANT") : "OWNER-OCCUPIED") + '</b></div><h3>' + esc(property.name) + '</h3><div class="asset-value-row"><div><small>CURRENT ESTIMATED VALUE</small><strong>' + moneyLabel(property.marketValueMinor) + '</strong></div><div><small>ESTIMATED EQUITY</small><strong>' + moneyLabel(equity) + '</strong></div></div><div class="asset-detail-grid"><div><small>ACQUISITION COST</small><b>' + moneyLabel(property.costBasisMinor) + '</b></div><div><small>MORTGAGE BALANCE</small><b>' + moneyLabel(debt) + '</b></div><div><small>RENT / WEEK</small><b>' + (property.use === "rental" && property.occupied ? moneyLabel(property.weeklyRentMinor) : "—") + '</b></div><div><small>UPKEEP / WEEK</small><b>' + moneyLabel(property.weeklyMaintenanceMinor) + '</b></div></div><div class="asset-condition"><div><small>PROPERTY CONDITION</small><b>' + property.condition + '/100</b></div><div class="meter"><i style="width:' + property.condition + '%"></i></div></div><div class="asset-actions"><form data-asset-form="ASSET_SET_PROPERTY_USE"><input type="hidden" name="propertyId" value="' + property.id + '"><label>Usage<select name="use"><option value="rental" ' + (property.use === "rental" ? "selected" : "") + '>Rental investment</option><option value="owner-occupied" ' + (property.use === "owner-occupied" ? "selected" : "") + '>Owner-occupied</option></select></label><button class="secondary-button" type="submit">Update use</button></form><button class="secondary-button" type="button" data-asset-action="ASSET_MAINTAIN_PROPERTY" data-property-id="' + property.id + '">Maintain</button><button class="danger-button" type="button" data-asset-action="ASSET_SELL_PROPERTY" data-property-id="' + property.id + '">Sell property</button></div></article>';
  }).join("");

  const collectibleCards = COLLECTIBLE_CATALOG.map(item => {
    const owned = collectiblesOwned.has(item.id), acquisition = Math.ceil(item.priceMinor * 150 / 10000);
    return '<article class="asset-catalog-card"><div class="asset-card-top"><span>' + esc(item.category.toUpperCase()) + '</span><b>' + esc(item.risk.toUpperCase()) + '</b></div><h3>' + esc(item.name) + '</h3><p>' + esc(item.description) + '</p><div class="asset-price">' + moneyLabel(item.priceMinor) + ' <small>Credits · indicative appraisal</small></div><div class="asset-detail-grid"><div><small>ACQUISITION FEE</small><b>' + moneyLabel(acquisition) + '</b></div><div><small>SALE LIQUIDITY DISCOUNT</small><b>' + (item.liquidityBps / 100).toFixed(2) + '%</b></div><div><small>CARE COST</small><b>' + moneyLabel(item.maintenanceMinor) + '</b></div><div><small>VALUATION RISK</small><b>' + esc(item.risk) + '</b></div></div>' + (owned ? '<div class="asset-owned-label">ALREADY COLLECTED</div>' : '<form class="asset-purchase-form" data-asset-form="ASSET_BUY_COLLECTIBLE"><input type="hidden" name="catalogId" value="' + item.id + '"><button class="primary-button" type="submit">Acquire collectible</button></form>') + '</article>';
  }).join("");

  const collectibleHoldings = a.collectibles.map(item => {
    const change = item.marketValueMinor - item.costBasisMinor, discount = item.liquidityBps / 100;
    return '<article class="asset-holding-card"><div class="asset-card-top"><span>' + esc(item.category.toUpperCase()) + '</span><b>' + esc(item.condition + '/100 CONDITION') + '</b></div><h3>' + esc(item.name) + '</h3><div class="asset-value-row"><div><small>ESTIMATED APPRAISAL</small><strong>' + moneyLabel(item.marketValueMinor) + '</strong></div><div><small>UNREALIZED P/L</small><strong class="' + (change >= 0 ? "positive" : "negative") + '">' + (change >= 0 ? "+" : "") + moneyLabel(change) + '</strong></div></div><div class="asset-detail-grid"><div><small>ACQUISITION COST</small><b>' + moneyLabel(item.costBasisMinor) + '</b></div><div><small>EST. RESALE VALUE</small><b>' + moneyLabel(Math.floor(item.marketValueMinor * (10000 - item.liquidityBps) / 10000)) + '</b></div><div><small>LIQUIDITY DISCOUNT</small><b>' + discount.toFixed(2) + '%</b></div><div><small>CARE / SERVICE</small><b>' + moneyLabel(item.maintenanceMinor) + '</b></div></div><div class="asset-condition"><div><small>CONDITION</small><b>' + item.condition + '/100</b></div><div class="meter"><i style="width:' + item.condition + '%"></i></div></div><div class="asset-actions"><button class="secondary-button" type="button" data-asset-action="ASSET_MAINTAIN_COLLECTIBLE" data-collectible-id="' + item.id + '">Care & conserve</button><button class="danger-button" type="button" data-asset-action="ASSET_SELL_COLLECTIBLE" data-collectible-id="' + item.id + '">Sell collectible</button></div></article>';
  }).join("");

  const transactions = a.transactions.slice(0, 16).map(item => '<tr><td>' + esc(item.date) + '</td><td><b>' + esc(item.description) + '</b><small>' + esc(item.kind.replaceAll("_", " ")) + '</small></td><td class="money">' + moneyLabel(item.amountMinor) + '</td></tr>').join("");
  const mortgageDebt = a.properties.reduce((sum, property) => sum + (mortgageFor(property)?.status === "active" ? mortgageFor(property).principalMinor + mortgageFor(property).interestAccruedMinor : 0), 0);

  return '<section class="asset-overview-grid"><article class="market-overview-card"><small>PROPERTY VALUE</small><strong>' + moneyLabel(portfolio.propertyValue) + '</strong><span>' + portfolio.propertyCount + ' properties held</span></article><article class="market-overview-card"><small>COLLECTIBLES VALUE</small><strong>' + moneyLabel(portfolio.collectibleValue) + '</strong><span>' + portfolio.collectibleCount + ' collectibles held</span></article><article class="market-overview-card"><small>COMBINED UNREALIZED P/L</small><strong class="' + (portfolio.totalUnrealized >= 0 ? "positive" : "negative") + '">' + (portfolio.totalUnrealized >= 0 ? "+" : "") + moneyLabel(portfolio.totalUnrealized) + '</strong><span>Estimated values less acquisition cost</span></article><article class="market-overview-card"><small>PROPERTY MORTGAGES</small><strong>' + moneyLabel(mortgageDebt) + '</strong><span>Included in household liabilities</span></article></section>' +
    '<section class="panel"><div class="life-section-head"><div><label>YOUR REAL ESTATE</label><h2>Owned properties</h2><p>Market estimates affect net worth, while rent, upkeep, tax and mortgage service are recorded separately in the Finance ledger.</p></div><span class="phase-chip">' + a.properties.length + ' OWNED</span></div>' + (ownedProperties || '<div class="asset-empty">No property owned yet. Review the listings below and compare down payment, rent, upkeep and borrowing capacity.</div>') + '</section>' +
    '<section class="panel"><div class="life-section-head"><div><label>PROPERTY MARKET</label><h2>Available property listings</h2><p>Fictional listings with simplified financing. Mortgages use the National Union Bank rate model, a 20% minimum down payment and income-based borrowing limits.</p></div><span class="phase-chip">' + PROPERTY_LISTINGS.length + ' LISTED</span></div><div class="asset-catalog-grid">' + propertyCards + '</div><p class="asset-feedback" id="assetFeedback" role="status" aria-live="polite"></p></section>' +
    '<section class="panel"><div class="life-section-head"><div><label>YOUR COLLECTION</label><h2>Owned collectibles</h2><p>Collectibles are illiquid assets. Appraisals are estimates; resale discounts reflect the difficulty of finding a buyer.</p></div><span class="phase-chip">' + a.collectibles.length + ' HELD</span></div>' + (collectibleHoldings ? '<div class="asset-holding-grid">' + collectibleHoldings + '</div>' : '<div class="asset-empty">Your collection is empty. Collectibles can diversify your assets, but condition and resale liquidity matter.</div>') + '</section>' +
    '<section class="panel"><div class="life-section-head"><div><label>COLLECTIBLE MARKET</label><h2>Available valuables</h2><p>Acquisitions require cash and a separate 1.5% purchase fee. Values are simulated, not live appraisals.</p></div><span class="phase-chip">' + COLLECTIBLE_CATALOG.length + ' LISTED</span></div><div class="asset-catalog-grid">' + collectibleCards + '</div><p class="asset-feedback" id="collectibleFeedback" role="status" aria-live="polite"></p></section>' +
    '<section class="panel"><div class="life-section-head"><div><label>ASSET ACTIVITY</label><h2>Recent property and collectible transactions</h2><p>Purchases, maintenance, rental operations and sales are retained in the subledger and Finance journal.</p></div></div><div class="table-wrap"><table class="finance-table"><thead><tr><th>DATE</th><th>ACTIVITY</th><th class="money">AMOUNT</th></tr></thead><tbody>' + (transactions || '<tr><td colspan="3">No asset transactions recorded yet.</td></tr>') + '</tbody></table></div></section>';
}



function renderOwnershipPanel(state) {
  const o = state.ownership, p = getOwnershipPortfolio(o), cash = state.finance.accounts.find(a => a.id === "cash")?.balanceMinor ?? 0;
  const targets = OWNERSHIP_TARGETS.filter(t => !o.companies.some(c => c.id === t.id));
  const targetCards = targets.map(t => '<article class="business-company-card"><div class="business-company-top"><span>' + esc(t.sector.toUpperCase()) + '</span><b>' + esc(t.risk.toUpperCase()) + ' RISK</b></div><h3>' + esc(t.name) + '</h3><p>' + esc(t.description) + '</p><div class="asset-price">' + moneyLabel(t.askingPriceMinor) + ' <small>Credits · full acquisition</small></div><button class="primary-button" type="button" data-ownership-action="OWNERSHIP_ACQUIRE_TARGET" data-target-id="' + t.id + '" ' + (cash < t.askingPriceMinor ? 'disabled' : '') + '>Acquire 100% ownership</button></article>').join("");
  const companies = o.companies.map(c => {
    const h = c.shareholders.find(x => x.id === "player"), shares = h?.shares ?? 0, total = c.outstandingShares, pct = total ? (shares / total * 100).toFixed(2) : "0.00";
    const holders = c.shareholders.map(x => '<tr><td><b>' + esc(x.name) + '</b><small>' + esc(x.type) + '</small></td><td>' + x.shares.toLocaleString("en-US") + '</td><td>' + (x.shares / total * 100).toFixed(2) + '%</td><td class="money">' + moneyLabel(x.costBasisMinor) + '</td></tr>').join("");
    const candidates = c.shareholders.map(x => '<option value="' + x.id + '">' + esc(x.name) + '</option>').join("");
    const resolutions = c.resolutions.slice(0, 4).map(r => '<article class="business-manage-form"><h3>' + esc(r.title) + '</h3><small>' + esc(r.status.toUpperCase()) + (r.amountMinor ? ' · ' + moneyLabel(r.amountMinor) + ' Credits' : '') + '</small>' + (r.status === "open" ? '<div class="business-control-stack">' + ["for","against","abstain"].map(v => '<button class="secondary-button" type="button" data-ownership-action="OWNERSHIP_VOTE" data-company-id="' + c.id + '" data-resolution-id="' + r.id + '" data-vote="' + v + '">Vote ' + v + '</button>').join("") + '<button class="primary-button" type="button" data-ownership-action="OWNERSHIP_CLOSE_VOTE" data-company-id="' + c.id + '" data-resolution-id="' + r.id + '">Close vote</button></div>' : '<small>For: ' + (r.outcome?.votesFor ?? 0) + ' · Against: ' + (r.outcome?.votesAgainst ?? 0) + ' · Quorum: ' + (r.outcome?.quorum ? 'met' : 'not met') + '</small>') + '</article>').join("");
    return '<section class="panel ownership-company"><div class="life-section-head"><div><label>' + (c.acquired ? 'ACQUIRED COMPANY' : 'FOUNDED COMPANY') + ' / ' + esc(c.sector.toUpperCase()) + '</label><h2>' + esc(c.name) + '</h2><p>' + esc(c.description || 'Privately held company.') + '</p></div><span class="phase-chip">' + pct + '% OWNED</span></div><div class="business-overview-grid"><article class="market-overview-card"><small>ESTIMATED EQUITY</small><strong>' + moneyLabel(c.estimatedValueMinor) + '</strong><span>Indicative valuation</span></article><article class="market-overview-card"><small>COMPANY CASH</small><strong>' + moneyLabel(c.cashMinor) + '</strong><span>Separate company funds</span></article><article class="market-overview-card"><small>SHARE PRICE</small><strong>' + moneyLabel(c.sharePriceMinor) + '</strong><span>Per share</span></article><article class="market-overview-card"><small>SHAREHOLDER LOANS</small><strong>' + moneyLabel(c.loanBalanceMinor) + '</strong><span>Company debt</span></article></div><div class="table-wrap"><table class="finance-table"><thead><tr><th>SHAREHOLDER</th><th>SHARES</th><th>OWNERSHIP</th><th class="money">COST BASIS</th></tr></thead><tbody>' + holders + '</tbody></table></div><div class="business-management-grid"><form class="business-manage-form" data-ownership-form="OWNERSHIP_CONTRIBUTE_CAPITAL"><h3>Invest equity</h3><input type="hidden" name="companyId" value="' + c.id + '"><label>Credits<input name="amount" inputmode="decimal" required></label><small>New shares at current indicative price.</small><button class="primary-button" type="submit">Contribute capital</button></form><form class="business-manage-form" data-ownership-form="OWNERSHIP_TAKE_LOAN"><h3>Shareholder loan</h3><input type="hidden" name="companyId" value="' + c.id + '"><label>Credits<input name="amount" inputmode="decimal" required></label><small>Creates a repayable company liability.</small><button class="secondary-button" type="submit">Advance loan</button></form><form class="business-manage-form" data-ownership-form="OWNERSHIP_REPAY_LOAN"><h3>Loan repayment</h3><input type="hidden" name="companyId" value="' + c.id + '"><label>Credits<input name="amount" inputmode="decimal" required></label><small>Outstanding: ' + moneyLabel(c.loanBalanceMinor) + '</small><button class="secondary-button" type="submit" ' + (c.loanBalanceMinor ? '' : 'disabled') + '>Receive repayment</button></form><form class="business-manage-form" data-ownership-form="OWNERSHIP_PROPOSE_DIVIDEND"><h3>Propose dividend</h3><input type="hidden" name="companyId" value="' + c.id + '"><label>Credits<input name="amount" inputmode="decimal" required></label><small>Subject to retained earnings, debt and reserve.</small><button class="primary-button" type="submit">Submit for vote</button></form><form class="business-manage-form" data-ownership-form="OWNERSHIP_ISSUE_SHARES"><h3>Issue new shares</h3><input type="hidden" name="companyId" value="' + c.id + '"><label>Investor<select name="investorId"><option value="cedar-ridge-capital">Cedar Ridge Capital</option><option value="northstar-ventures">Northstar Ventures</option><option value="mira-chen">Mira Chen</option><option value="atlas-holdings">Atlas Holdings</option></select></label><label>Shares<input name="shares" type="number" min="1" value="10000" required></label><button class="secondary-button" type="submit">Issue shares</button></form><form class="business-manage-form" data-ownership-form="OWNERSHIP_BUYBACK_SHARES"><h3>Sell shares to company</h3><input type="hidden" name="companyId" value="' + c.id + '"><label>Shares<input name="shares" type="number" min="1" max="' + shares + '" value="' + Math.max(1, Math.floor(shares / 10)) + '" required ' + (shares ? '' : 'disabled') + '></label><small>Current holding: ' + shares.toLocaleString("en-US") + '</small><button class="secondary-button" type="submit" ' + (shares ? '' : 'disabled') + '>Request buyback</button></form></div><form class="business-form-inline" data-ownership-form="OWNERSHIP_CREATE_RESOLUTION"><input type="hidden" name="companyId" value="' + c.id + '"><label>Resolution title<input name="title" maxlength="100" required></label><label>Type<select name="resolutionType"><option value="CAPITAL_EXPANSION">Capital expansion</option><option value="EXECUTIVE_APPOINTMENT">Executive appointment</option><option value="ACQUISITION">Acquisition</option><option value="OTHER">Other</option></select></label><button class="secondary-button" type="submit">Open resolution</button></form><form class="business-form-inline" data-ownership-form="OWNERSHIP_APPOINT_EXECUTIVE"><input type="hidden" name="companyId" value="' + c.id + '"><label>Role<select name="role"><option>CEO</option><option>CFO</option><option>COO</option></select></label><label>Shareholder<select name="candidateId">' + candidates + '</select></label><button class="secondary-button" type="submit">Appoint executive</button></form>' + (resolutions ? '<h3 class="business-subtitle">Shareholder resolutions</h3><div class="business-management-grid">' + resolutions + '</div>' : '') + '<small>Issued: ' + c.issuedShares.toLocaleString("en-US") + ' / Authorized: ' + c.authorizedShares.toLocaleString("en-US") + ' · Base weekly profit rate: ' + (c.weeklyProfitBps / 100).toFixed(2) + '%</small></section>';
  }).join("");
  const formation = '<section class="panel"><div class="life-section-head"><div><label>ENTREPRENEURSHIP / PHASE 10</label><h2>Found your own company</h2><p>Invest household cash for founder shares. Company funds and personal funds remain separate.</p></div><span class="phase-chip">MINIMUM 250 CREDITS</span></div><form class="business-management-grid" data-ownership-form="OWNERSHIP_FOUND_COMPANY"><label>Company name<input name="name" minlength="3" maxlength="48" required></label><label>Sector<select name="sector">' + ["Technology","Consumer","Professional services","Healthcare","Logistics","Hospitality","Manufacturing"].map(x => '<option>' + x + '</option>').join("") + '</select></label><label>Founding capital<input name="amount" inputmode="decimal" placeholder="e.g. 2,500.00" required></label><label>Founder shares<input name="shares" type="number" min="1000" max="1000000" value="100000" required></label><label>Description<input name="description" maxlength="240"></label><button class="primary-button" type="submit">Found company</button></form><small>Household cash available: ' + moneyLabel(cash) + ' Credits. Founder begins with 100% ownership.</small></section>';
  return '<section class="panel"><div class="life-section-head"><div><label>OWNERSHIP PORTFOLIO / PHASE 10</label><h2>Build, own and govern companies</h2><p>Company ownership is separate from Phase 9 operating mandates. Estimated valuations are not liquid cash.</p></div><span class="phase-chip">' + p.companyCount + ' COMPANIES</span></div><div class="business-overview-grid"><article class="market-overview-card"><small>INVESTED CAPITAL</small><strong>' + moneyLabel(p.investedMinor) + '</strong><span>Private-equity cost basis</span></article><article class="market-overview-card"><small>ESTIMATED EQUITY VALUE</small><strong>' + moneyLabel(p.estimatedValueMinor) + '</strong><span>Indicative portfolio value</span></article><article class="market-overview-card"><small>UNREALIZED CHANGE</small><strong class="' + (p.unrealizedMinor >= 0 ? 'positive' : 'negative') + '">' + (p.unrealizedMinor >= 0 ? '+' : '') + moneyLabel(p.unrealizedMinor) + '</strong><span>Not realized until a sale</span></article><article class="market-overview-card"><small>HOUSEHOLD CASH</small><strong>' + moneyLabel(cash) + '</strong><span>Available personal liquidity</span></article></div></section>' + formation + (companies || '<section class="panel"><p>No companies owned yet. Found a company or acquire a target to start your portfolio.</p></section>') + '<section class="panel"><div class="life-section-head"><div><label>MERGERS & ACQUISITIONS</label><h2>Acquire an established company</h2><p>Purchase 100% of a fictional private company using household cash.</p></div><span class="phase-chip">' + targets.length + ' TARGETS</span></div><div class="business-company-grid">' + (targetCards || '<p>No acquisition targets remain.</p>') + '</div></section><p class="business-feedback" id="ownershipFeedback" role="status" aria-live="polite"></p>';
}

export function renderBusinessesView(state) {
  if (!state || !state.life?.character || !state.businesses || !state.ownership) return '<section class="panel">' + emptyState("building", "Start a simulation to operate a business", "Create a character to review company operating mandates and business opportunities.", "SIMULATION REQUIRED") + '<a class="primary-button" href="#/overview" data-route="overview">Go to Overview</a></section>';

  const character = state.life.character, businesses = state.businesses, mandate = businesses.mandate;
  const requirementText = company => Object.entries(company.requirements).map(([key, value]) => key.replace(/([A-Z])/g, " $1").toUpperCase() + " " + value + "+").join(" · ");
  const eligible = company => Object.entries(company.requirements).every(([key, value]) => (character.skills?.[key] ?? 0) >= value);

  if (!mandate) {
    const cards = BUSINESS_COMPANIES.map(company => {
      const canApply = eligible(company);
      const products = company.products.map(item => esc(item.name)).join(" · ");
      return '<article class="business-company-card"><div class="business-company-top"><span>' + esc(company.sector.toUpperCase()) + '</span><b>' + esc(company.model.toUpperCase()) + '</b></div><h3>' + esc(company.name) + '</h3><h4>' + esc(company.branchName) + '</h4><p>' + esc(company.description) + '</p><div class="business-company-stats"><div><small>MANAGER PAY / WEEK</small><strong>' + moneyLabel(company.managerPayMinor) + ' Credits</strong></div><div><small>INITIAL TEAM</small><strong>' + company.defaultStaff + ' employees</strong></div><div><small>OPERATING CASH</small><strong>' + moneyLabel(company.openingCashMinor) + ' Credits</strong></div><div><small>PRODUCT / SERVICE LINES</small><strong>' + company.products.length + '</strong></div></div><div class="business-company-products"><small>OFFERING</small><span>' + products + '</span></div><div class="business-company-requirements"><small>MANDATE REQUIREMENTS</small><span>' + esc(requirementText(company)) + '</span></div><button class="primary-button" type="button" data-business-accept="' + company.id + '" ' + (canApply ? "" : "disabled") + '>Accept operating mandate</button>' + (canApply ? '<small class="business-eligibility">Your current skills meet this mandate.</small>' : '<small class="business-lock">Your current skills do not meet this mandate yet. Develop the listed skills in Personal.</small>') + '</article>';
    }).join("");
    const archives = businesses.history.map(item => '<tr><td><b>' + esc(item.branchName) + '</b><small>' + esc(item.companyName) + ' · TURNS ' + item.openedAtTurn + '–' + item.closedAtTurn + '</small></td><td class="money">' + moneyLabel(item.revenueMinor) + '</td><td class="money ' + (item.operatingProfitMinor >= 0 ? "positive" : "negative") + '">' + (item.operatingProfitMinor >= 0 ? "+" : "") + moneyLabel(item.operatingProfitMinor) + '</td><td>' + item.managerScore + '/100</td></tr>').join("");
    return renderOwnershipPanel(state) + '<section class="business-intro"><div><label>BUSINESS OPERATIONS / PHASE 09</label><h2>Run the operation. Earn the reputation.</h2><p>Accept a management mandate from an established company. You control the branch operation, not its ownership. The parent company funds the unit and retains its equity.</p></div><span class="phase-chip">MANAGEMENT CONTRACTS</span></section><section class="business-company-grid">' + cards + '</section>' +
      (archives ? '<section class="panel"><div class="life-section-head"><div><label>PREVIOUS MANDATES</label><h2>Operating record</h2><p>Completed mandates remain in your career history. Branch capital and residual assets return to the parent company.</p></div></div><div class="table-wrap"><table class="finance-table"><thead><tr><th>BRANCH</th><th class="money">SALES</th><th class="money">OPERATING RESULT</th><th>MANAGER SCORE</th></tr></thead><tbody>' + archives + '</tbody></table></div></section>' : '') +
      '<p class="business-feedback" id="businessFeedback" role="status" aria-live="polite"></p>';
  }

  const summary = getBusinessSummary(businesses), m = mandate;
  const products = m.products.map(product => {
    const margin = product.priceMinor - product.unitCostMinor;
    const marginPct = product.priceMinor ? (margin / product.priceMinor * 100).toFixed(1) : "0.0";
    const pending = m.purchaseOrders.filter(order => order.productId === product.id && order.status === "pending").reduce((sum, order) => sum + order.units, 0);
    return '<article class="business-product-card"><div class="business-product-head"><div><small>PRODUCT / SERVICE LINE</small><h3>' + esc(product.name) + '</h3></div><span>' + product.baseDemand + ' DEMAND / WK</span></div><div class="business-product-metrics"><div><small>SELLING PRICE</small><strong>' + moneyLabel(product.priceMinor) + '</strong></div><div><small>UNIT COST</small><strong>' + moneyLabel(product.unitCostMinor) + '</strong></div><div><small>GROSS MARGIN</small><strong>' + marginPct + '%</strong></div></div><div class="business-stock-row"><span>ON HAND <b>' + product.inventoryUnits + ' units</b></span><span>IN TRANSIT <b>' + pending + '</b></span><span>STOCK VALUE <b>' + moneyLabel(product.inventoryValueMinor) + '</b></span></div><div class="business-control-stack"><form class="business-form-inline" data-business-form="BUSINESS_SET_PRICE"><input type="hidden" name="productId" value="' + product.id + '"><label>New selling price<input name="price" inputmode="decimal" value="' + (product.priceMinor / 100).toFixed(2) + '" required></label><button class="secondary-button" type="submit">Update price</button></form><form class="business-form-inline" data-business-form="BUSINESS_ORDER_INVENTORY"><input type="hidden" name="productId" value="' + product.id + '"><label>Supplier<select name="supplierId">' + BUSINESS_SUPPLIERS.map(supplier => '<option value="' + supplier.id + '">' + esc(supplier.name) + ' · ' + supplier.leadWeeks + ' wk</option>').join("") + '</select></label><label>Units<input name="units" type="number" min="1" max="500" value="10" required></label><button class="secondary-button" type="submit">Order stock</button></form></div></article>';
  }).join("");

  const supplierRows = BUSINESS_SUPPLIERS.map(supplier => '<tr><td><b>' + esc(supplier.name) + '</b><small>' + esc(supplier.tier) + '</small></td><td>' + supplier.leadWeeks + ' weeks</td><td>' + (supplier.reliabilityBps / 100).toFixed(1) + '%</td><td>' + moneyLabel(supplier.shippingMinor) + '</td><td>' + esc(supplier.description) + '</td></tr>').join("");
  const orders = m.purchaseOrders.filter(order => order.status === "pending").map(order => {
    const product = m.products.find(item => item.id === order.productId), supplier = BUSINESS_SUPPLIERS.find(item => item.id === order.supplierId);
    return '<tr><td><b>' + esc(product?.name ?? order.productId) + '</b><small>' + esc(supplier?.name ?? order.supplierId) + '</small></td><td>' + order.units + '</td><td>' + esc(order.deliveryTurn <= state.calendar.turn ? "Due" : "Turn " + order.deliveryTurn) + '</td><td class="money">' + moneyLabel(order.goodsValueMinor + order.shippingMinor) + '</td></tr>';
  }).join("");
  const history = m.history.slice(0, 12).map(item => '<tr><td>' + esc(item.date) + '</td><td class="money">' + moneyLabel(item.revenueMinor) + '</td><td class="money">' + moneyLabel(item.cogsMinor) + '</td><td class="money ' + (item.operatingProfitMinor >= 0 ? "positive" : "negative") + '">' + (item.operatingProfitMinor >= 0 ? "+" : "") + moneyLabel(item.operatingProfitMinor) + '</td><td>' + item.unitsSold + '</td><td>' + item.managerScore + '/100</td></tr>').join("");
  const recentTransactions = m.transactions.slice(0, 12).map(item => '<tr><td>' + esc(item.date) + '</td><td><b>' + esc(item.description) + '</b><small>' + esc(item.kind.replaceAll("_", " ")) + '</small></td><td class="money">' + moneyLabel(item.amountMinor) + '</td></tr>').join("");
  const payableText = summary.payablesMinor > 0 ? '<span class="business-warning">Outstanding obligations: ' + moneyLabel(summary.payablesMinor) + ' Credits. The branch is deferring payments because its operating cash is insufficient.</span>' : '<span class="business-good">Operating obligations are currently settled.</span>';

  return '<section class="business-active-head"><div><label>ACTIVE OPERATING MANDATE / ' + esc(m.sector.toUpperCase()) + '</label><h2>' + esc(m.branchName) + '</h2><p>' + esc(m.companyName) + ' · ' + esc(m.model) + ' · Started turn ' + m.openedAtTurn + '</p></div><div class="business-score"><small>MANAGER PERFORMANCE</small><strong>' + m.managerScore + '<span>/100</span></strong><div class="meter"><i style="width:' + m.managerScore + '%"></i></div></div></section>' +
    '<section class="business-overview-grid"><article class="market-overview-card"><small>BRANCH SALES</small><strong>' + moneyLabel(summary.revenueMinor) + '</strong><span>Lifetime sales to date</span></article><article class="market-overview-card"><small>OPERATING RESULT</small><strong class="' + (summary.profitMinor >= 0 ? "positive" : "negative") + '">' + (summary.profitMinor >= 0 ? "+" : "") + moneyLabel(summary.profitMinor) + '</strong><span>Revenue less recorded expenses</span></article><article class="market-overview-card"><small>OPERATING CASH</small><strong>' + moneyLabel(summary.cashMinor) + '</strong><span>Parent-company branch funds</span></article><article class="market-overview-card"><small>INVENTORY ASSETS</small><strong>' + moneyLabel(summary.inventoryMinor + summary.transitMinor) + '</strong><span>On hand plus in transit</span></article></section>' +
    '<section class="business-status-strip"><div><small>CUSTOMER SATISFACTION</small><b>' + m.customerSatisfaction + '/100</b></div><div><small>TEAM SIZE</small><b>' + m.staffCount + ' employees</b></div><div><small>UNITS SOLD</small><b>' + summary.totalUnitsSold.toLocaleString("en-US") + '</b></div><div><small>STOCKOUTS</small><b>' + summary.totalStockouts.toLocaleString("en-US") + '</b></div><div><small>MANAGER PAY / WEEK</small><b>' + moneyLabel(m.managerPayMinor) + ' Credits</b></div></section>' +
    '<section class="panel"><div class="life-section-head"><div><label>OPERATIONS CONTROL</label><h2>Manage your branch</h2><p>Staffing changes apply to future payroll. Marketing is paid immediately and boosts demand for four turns. At least 8 hours of weekly side work is recommended for stable management performance.</p></div><span class="phase-chip">8 HOUR COMMITMENT</span></div><div class="business-management-grid"><form class="business-manage-form" data-business-form="BUSINESS_SET_STAFFING"><h3>Staffing plan</h3><label>Employees<select name="staffCount">' + Array.from({length:10},(_,i)=>'<option value="' + (i+1) + '" ' + (i+1===m.staffCount?"selected":"") + '>' + (i+1) + ' employees</option>').join("") + '</select></label><small>Weekly payroll: ' + moneyLabel(m.staffCount * m.staffWageMinor) + ' Credits</small><button class="primary-button" type="submit">Update team</button></form><form class="business-manage-form" data-business-form="BUSINESS_MARKETING_CAMPAIGN"><h3>Marketing campaign</h3><label>Campaign budget<input name="amount" inputmode="decimal" placeholder="e.g. 100.00" value="100.00" required></label><small>50–1,500 Credits. Funded from branch operating cash.</small><button class="primary-button" type="submit">Launch campaign</button></form><div class="business-manage-form business-working-capital"><h3>Branch health</h3><b>' + (summary.payablesMinor > 0 ? "PAYABLES OUTSTANDING" : "CURRENT") + '</b><small>Cash: ' + moneyLabel(summary.cashMinor) + ' Credits</small><small>Payables: ' + moneyLabel(summary.payablesMinor) + ' Credits</small>' + payableText + '</div></div><p class="business-feedback" id="businessFeedback" role="status" aria-live="polite"></p></section>' +
    '<section class="panel"><div class="life-section-head"><div><label>PRODUCT & SERVICE MANAGEMENT</label><h2>Pricing and inventory</h2><p>Set a selling price, compare unit economics and replenish stock. Supplier orders are prepaid and delivered after their lead time.</p></div><span class="phase-chip">' + m.products.length + ' LINES</span></div><div class="business-product-grid">' + products + '</div></section>' +
    '<section class="panel"><div class="life-section-head"><div><label>SUPPLIER NETWORK</label><h2>Available suppliers</h2><p>Value suppliers trade price for lead time; express partners charge more for faster and more reliable replenishment.</p></div><span class="phase-chip">' + BUSINESS_SUPPLIERS.length + ' PARTNERS</span></div><div class="table-wrap"><table class="finance-table"><thead><tr><th>SUPPLIER</th><th>LEAD TIME</th><th>RELIABILITY</th><th>SHIPPING</th><th>PROFILE</th></tr></thead><tbody>' + supplierRows + '</tbody></table></div><h3 class="business-subtitle">Pending purchase orders</h3><div class="table-wrap"><table class="finance-table"><thead><tr><th>PRODUCT / SUPPLIER</th><th>UNITS</th><th>EXPECTED DELIVERY</th><th class="money">ORDER VALUE</th></tr></thead><tbody>' + (orders || '<tr><td colspan="4">No purchase orders in transit.</td></tr>') + '</tbody></table></div></section>' +
    '<section class="panel"><div class="life-section-head"><div><label>WEEKLY PERFORMANCE</label><h2>Operating results</h2><p>Branch results include sales, cost of goods, wages, manager compensation, premises, utilities, shipping and marketing.</p></div><span class="phase-chip">52 WEEK HISTORY</span></div><div class="table-wrap"><table class="finance-table"><thead><tr><th>DATE</th><th class="money">SALES</th><th class="money">COGS</th><th class="money">OPERATING RESULT</th><th>UNITS</th><th>MANAGER</th></tr></thead><tbody>' + (history || '<tr><td colspan="6">Advance a turn to record your first operating week.</td></tr>') + '</tbody></table></div></section>' +
    '<section class="panel"><div class="life-section-head"><div><label>BRANCH JOURNAL</label><h2>Recent business activity</h2><p>These are company branch records, kept separate from the household Finance ledger.</p></div><span class="phase-chip">' + m.ledger.entries.length + ' ENTRIES</span></div><div class="table-wrap"><table class="finance-table"><thead><tr><th>DATE</th><th>ACTIVITY</th><th class="money">AMOUNT</th></tr></thead><tbody>' + (recentTransactions || '<tr><td colspan="3">No branch transactions yet.</td></tr>') + '</tbody></table></div></section>' +
    '<section class="business-contract-note"><div><b>Operating mandate only</b><span>The parent company owns the branch, its cash, inventory and equipment. Your income is the manager compensation actually paid. No shares, dividends, acquisition rights or personal ownership are created in Phase 9.</span></div><button class="danger-button" type="button" data-business-action="BUSINESS_END_MANDATE">End operating mandate</button></section>' + renderOwnershipPanel(state);
}
